package com.example.survivor.game;
import java.util.Scanner;
/** A resumable conversation; each answer is kept in the world's save. */
final class SemenHeartTalk {
 private static final String[] TITLES={"Не смотри на звёзды","А что ты вообще помнишь?","Посмотри наверх","А если ты уже умер?","Самая неприятная мысль"};
 private static final String[] PROMPTS={"Семён сидит на капоте старой машины. Рядом лежит красный шарф, который Джон принёс из квартиры.\n\nПри появлении Джона мужчина поднимает голову.\n\nСемён: О, блядь. Опять ты.\n\nДжон: И тебе добрый вечер.\n\nСемён: Подойди сюда. Только машину не трогай.\n\nДжон: Что опять?\n\nСемён: Ты не замечал, что у нас тут всё какое-то... неправильное?\n\nДжон: Кроме ходячих трупов?\n\nСемён: Да не про них я! С ними всё понятно. Бегают, жрут, воняют. Обычные местные жители, только коммуналку не платят.\n\nДжон: Тогда что?\n\nСемён: Сядь. Сейчас расскажу одну херню. Только не перебивай.","Семён спрыгивает с капота.\n\nСемён: Слушай сюда. Ты помнишь, что делал за день до начала всей этой херни?\n\nДжон: ...\n\nСемён: Не в общем. Не «работал, ел, спал». Конкретно. Во сколько проснулся? Что ел? С кем говорил?","Семён неожиданно указывает пальцем на небо.\n\nСемён: Звёзды видишь?\n\nДжон: Вижу.\n\nСемён: Вчера я сидел тут же. Смотрел наверх. Долго смотрел. Знаешь, что заметил?\n\nДжон: Что у тебя слишком много свободного времени?\n\nСемён: Тоже. Но не это.\n\nОн достаёт помятый блокнот.\n\nНа странице несколько грубых рисунков созвездий.\n\nСемён: Я их зарисовал. Позавчера тоже. И вот что странно: я не смог заметить, чтобы они хоть немного сдвинулись.\n\nДжон: Может, плохо смотрел?\n\nСемён: Может. Я же не астроном, мать его. Но раньше мне казалось, что небо меняется.\n\nДжон: Звёзды не обязаны заметно менять положение, пока ты на них пять минут пялишься.\n\nСемён: Так я не пять минут пялился!\n\nДжон: И сколько?\n\nСемён: ...Не знаю.\n\nПауза.\n\nСемён: Вот видишь? Даже здесь я не могу тебе нормально ответить.","Семён закрывает блокнот.\n\nСемён: Ладно. Допустим, это не сон.\n\nДжон: Наконец-то.\n\nСемён: Не радуйся. Есть вариант похуже.\n\nДжон: Ещё один?\n\nСемён: А если мы умерли?\n\nДжон молчит.\n\nСемён: Не обязательно сейчас. Может, ещё до всей этой заразы. Может, в первые дни. И всё это просто... то, что осталось.\n\nДжон: А заражённые?\n\nСемён: Не знаю. Может, страхи. Может, воспоминания. Может, вообще настоящие заражённые, а мы два дебила, которые пытаются придумать себе красивое объяснение.\n\nДжон: Второе звучит убедительнее.\n\nСемён: Меня тоже бесит, насколько оно убедительное.","Джон собирается уходить.\n\nСемён: Стой. Последний вопрос.\n\nДжон: Ну?\n\nСемён: Допустим, ты найдёшь свой военный склад. Тебя заберут. Вывезут отсюда. Всё закончится.\n\nДжон: Было бы неплохо.\n\nСемён: А если не закончится?\n\nДжон: В смысле?\n\nСемён: А если ты приедешь в другое место, а там опять те же дома, те же люди, те же поиски еды? Просто вывеска другая.\n\nДжон: Ты хочешь сказать, что мы ходим по кругу?\n\nСемён: Я хочу сказать, что ты ни хрена не знаешь, куда тебя ведут.\n\nДжон: Зато ты знаешь?\n\nСемён: Нет.\n\nОн усмехается.\n\nСемён: Вот поэтому я и сижу в машине, а ты куда-то идёшь."};
 private static final String[][] OPTIONS={{"Ну, удиви меня","Опять твоя теория со сном?","Только давай без философской хуйни"},{"Помню достаточно","Не помню. Слишком много всего произошло","А ты сам-то помнишь?","Может, я уже умер. Тебя такой ответ устроит?"},{"Ты просто накручиваешь себя","А если ты действительно что-то заметил?","Покажи свои рисунки","Мне кажется, ты несколько ночей нормально не спал"},{"Если я мёртв, почему мне больно?","То есть мне теперь можно не искать эвакуацию?","А если это всё мой сон, кто тогда ты?","Тогда почему бы тебе просто не проверить?"},{"Я всё равно найду этот склад","Может, ты и прав","Ты слишком много думаешь","Завтра посмотрю на звёзды","Знаешь что, Семён? Иди ты нахуй"}};
 private static final String[][] REPLIES={{"Семён: Ты когда-нибудь во сне понимал, что спишь?\n\nДжон: Было такое.\n\nСемён: А потом просыпался? По-настоящему?\n\nДжон: Вроде.\n\nСемён: Вот именно. Вроде.","Семён: Ага. Опять моя теория. А ты давай расскажи, почему она херовая.\n\nДжон: Потому что я могу потрогать эту машину.\n\nСемён: Ну потрогай. Во сне тоже можешь. Сильный аргумент, профессор.","Семён: Не переживай. Философы давно все сдохли. Теперь только я остался.\n\nДжон: Очень жаль человечество.\n\nСемён: Да ему и раньше особо не везло."},{"Семён: Тогда расскажи.\n\nДжон: Я не собираюсь тебе свою биографию пересказывать.\n\nСемён: Вот. А я ведь даже не спрашивал, сколько тебе лет и где ты работал. Я спросил про один сраный день.","Семён: Может быть. А может, никакого дня и не было.\n\nДжон: И что, по-твоему, я появился сразу здесь?\n\nСемён: А ты можешь доказать обратное?","Семён ненадолго замолкает.\n\nСемён: Нет.\n\nДжон: Вот и всё.\n\nСемён: Не вот и всё. В том-то и проблема, блядь. Я тоже не помню.","Семён: А вот это уже интереснее.\n\nДжон: Я пошутил.\n\nСемён: А я нет."},{"Семён: Возможно. Тогда объясни, почему меня это не отпускает.","Семён: Тогда я понятия не имею, что с этим делать. Я, блядь, электрик. Моё дело провода соединять, а не устройство вселенной проверять.","Семён протягивает блокнот.\n\nНа страницах почти одинаковые схемы звёзд. Но даты подписаны неровно, а на одной странице их вовсе нет.\n\nДжон: И это всё?\n\nСемён: А что ты хотел? Фотографию Бога с подписью «эксперимент удался»?","Семён: Вот это впервые за вечер звучит разумно.\n\nДжон: Ну так иди спать.\n\nСемён: Ага. Чтобы проснуться здесь же. Очень заманчивое предложение."},{"Семён: А тебе во сне никогда больно не было?\n\nДжон: Было.\n\nСемён: Ну вот.\n\nДжон: Это ничего не доказывает.\n\nСемён: А я и не говорил, что доказывает!","Семён: Не знаю. Может, эвакуация и есть способ проснуться.\n\nДжон: Или просто эвакуация.\n\nСемён: Или просто эвакуация. Вот из-за таких, как ты, хорошие безумные теории и разваливаются.","Семён: Без понятия. Но если ты меня придумал, то у тебя пиздец какие проблемы с воображением.\n\nДжон: Почему?\n\nСемён: Мог придумать красивую бабу, океан, яхту. А придумал меня, сорокавосьмилетнего мужика, который живёт в машине и жрёт холодную фасоль.","Семён резко перестаёт улыбаться.\n\nСемён: Не надо.\n\nДжон: Что?\n\nСемён: Я уже видел людей, которые пытались доказать себе, что ничего не настоящее. Хреново кончилось.\n\nПауза.\n\nСемён: Если это сон, я хочу однажды проснуться. А если нет, то мне ещё пожить охота."},{"Семён: Найди. И если там действительно нормальные люди, пришли кого-нибудь за мной. Только предупреди, что я иногда несу хуйню.","Семён: Надеюсь, что нет. Честно. Мне бы больше понравилось оказаться обычным психом, чем единственным умным человеком в этом кошмаре.","Семён: А ты слишком мало. Ничего, на двоих сойдёт.","Семён: Посмотри. Только записывай время. А то я уже сам не понимаю, что видел, а что додумал.","Семён: АХАХА! Вот! Вот это я понимаю! Настоящий человек! Моё подсознание так изящно послать меня не способно!"}};
 private static final String ENDING="Джон отходит от машины.\n\nСемён: Эй!\n\nДжон: Чего ещё?!\n\nСемён: Если завтра проснёшься в своей кровати, не забудь про меня.\n\nДжон: А если не проснусь?\n\nСемён: Тогда приходи. Посидим, ещё какую-нибудь хуйню придумаем.\n\nСемён забирается обратно в автомобиль и закрывает дверь.\n\nНа лобовом стекле всё ещё написано:\n\n«НЕ БУДИТЬ».\n\nДжон продолжает путь.\n\nОн не поверил Семёну. По крайней мере, ему хотелось так думать.\n\nНо перед выходом из двора зачем-то посмотрел на небо.";
 static boolean evening(WorldStories w){int t=w.minuteOfDay();return t>=1080||t<360;}
 static boolean available(SemenStory s,WorldStories w){return s.semen_story_completed&&!s.pendingResponse&&!s.semen_trust_lost&&s.canApproach()&&s.heartStage<5&&(s.heartStage>0||evening(w));}
 static String hint(SemenStory s,WorldStories w){
  if(s.semen_trust_lost)return "Семён ушёл";
  if(!s.semen_story_completed||s.pendingResponse)return "Сперва выполните задание для Семёна";
  if(!s.canApproach())return "Семён просит вернуться позже";
  if(s.heartStage>=5)return "Разговор состоялся";
  if(s.heartStage==0&&!evening(w))return "Приходите вечером или ночью";
  return s.heartStage>0?"Продолжить разговор":"Поговорить с Семёном";
 }
 static void open(SemenStory s,WorldStories w,Scanner scanner){
  if(!available(s,w))return;
  while(s.heartStage<5){int stage=s.heartStage;GameIO.storyMenu(TITLES[stage],PROMPTS[stage]);
   for(int i=0;i<OPTIONS[stage].length;i++)GameIO.action(i+1,OPTIONS[stage][i]);
   GameIO.action(0,"Продолжить позже");int c=SurvivalSystems.choice(scanner);if(c<1||c>OPTIONS[stage].length)return;
   if(s.heartAnswers==null)s.heartAnswers=new int[5];s.heartAnswers[stage]=c;s.heartStage=stage+1;
   if(s.heartStage==5)w.note("А ты точно проснулся?","Семён рассказал Джону свои тревожные догадки о сне и звёздах. Он сам не уверен, что они верны.");
   GameIO.checkpoint();ResidentialStories.pause(TITLES[stage],REPLIES[stage][c-1]+(stage==4?"\n\n"+ENDING:""),scanner);
  }
 }
}
